import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, useMapEvents, GeoJSON, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

// --- Component điều khiển Map (Zoom/Fly) ---
function MapController({ zones, selectedDistrict, districts }) {
  const map = useMap();
  useEffect(() => {
    if (selectedDistrict) {
      const dist = districts.find(d => d.id === selectedDistrict);
      if (dist && dist.center_lat) {
        map.flyTo([dist.center_lat, dist.center_lng], 14); // Zoom sâu vào quận được chọn
      }
    } else if (zones.length > 0) {
      // Nếu không chọn quận nào (chế độ xem tất cả), tự động fit toàn bộ zones
      const bounds = [];
      zones.forEach(z => {
        if (z.center_lat && z.center_lng) bounds.push([z.center_lat, z.center_lng]);
      });
      if (bounds.length > 0) map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50] });
    }
  }, [selectedDistrict, zones, districts, map]);
  return null;
}

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [districts, setDistricts] = useState([]);
  const [allZones, setAllZones] = useState([]);
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  
  // State quản lý Form & UI
  const [editingZone, setEditingZone] = useState(null);
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 21.0285, center_lng: 105.8542 });
  const [success, setSuccess] = useState("");

  useEffect(() => {
    fetchDistricts();
    fetchAllZones();
  }, []);

  const fetchDistricts = async () => {
    const res = await fetch(`${API_BASE}/districts`);
    setDistricts(await res.json());
  };

  const fetchAllZones = async () => {
    const res = await fetch(`${API_BASE}/zones`);
    setAllZones(await res.json());
  };

  // --- Logic lọc Zones theo Quận ---
  const displayedZones = useMemo(() => {
    // Nếu chọn quận: chỉ hiện zone của quận đó. Nếu không chọn: hiện tất cả.
    return selectedDistrict 
      ? allZones.filter(z => z.district_id === selectedDistrict) 
      : allZones;
  }, [allZones, selectedDistrict]);

  // --- API: Xóa Zone ---
  const handleDeleteZone = async (zoneId) => {
    if (!window.confirm("Bạn có chắc chắn muốn xóa Zone này không?")) return;
    try {
      const res = await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
      if (res.ok) {
        setSuccess("Đã xóa Zone thành công!");
        fetchAllZones();
      }
    } catch (err) { console.error(err); }
  };

  // --- API: Cập nhật thông tin Zone ---
  const handleUpdateZone = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_BASE}/zones/${editingZone.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: editingZone.name,
          num_customers: parseInt(editingZone.num_customers),
          num_orders: parseInt(editingZone.num_orders),
          revenue: parseFloat(editingZone.revenue)
        }),
      });
      if (res.ok) {
        setSuccess("Cập nhật dữ liệu Zone thành công!");
        setEditingZone(null);
        fetchAllZones();
      }
    } catch (err) { console.error(err); }
  };

  const getZoneColor = (id) => `hsl(${(id * 137.5) % 360}, 70%, 50%)`;

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>🏢 Quản lý Phân vùng Thương mại</h1>
          <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
        </div>
      </header>

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <div className="sidebar-title">📍 Danh sách Quận</div>
          <nav className="nav-menu">
            <button 
              className={`nav-item ${selectedDistrict === null ? "active" : ""}`}
              onClick={() => setSelectedDistrict(null)}
            >
              🌍 Xem Toàn Bản Đồ
            </button>
            <hr />
            {districts.map(d => (
              <button 
                key={d.id}
                className={`nav-item ${selectedDistrict === d.id ? "active" : ""}`}
                onClick={() => setSelectedDistrict(d.id)}
              >
                🏙️ {d.name}
              </button>
            ))}
          </nav>
        </aside>

        <main className="main-content">
          {success && <div className="success-message" onClick={() => setSuccess("")}>{success} [X]</div>}

          <div className="content-section">
            <div className="section-header">
              <h2>{selectedDistrict ? `Quản lý Zones: ${districts.find(d=>d.id===selectedDistrict)?.name}` : "Tổng quan tất cả các Zones"}</h2>
              <button className="btn-primary" onClick={() => setShowDistrictForm(true)}>➕ Thêm Quận Mới</button>
            </div>

            {/* Bản đồ hiển thị Zones */}
            <div className="map-container" style={{ height: '450px', borderRadius: '12px', border: '1px solid #ddd' }}>
              <MapContainer center={[21.0285, 105.8542]} zoom={12} style={{ height: '100%' }}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                <MapController zones={displayedZones} selectedDistrict={selectedDistrict} districts={districts} />
                
                {displayedZones.map(z => (
                  <GeoJSON 
                    key={`${selectedDistrict}-${z.id}`} 
                    data={z.geometry} 
                    style={{ color: getZoneColor(z.id), fillOpacity: 0.5, weight: 2 }}
                  >
                    <Tooltip permanent direction="center" className="zone-label">{z.name}</Tooltip>
                    <Popup>
                        <strong>{z.name}</strong><br/>
                        Mã: {z.zone_code}
                    </Popup>
                  </GeoJSON>
                ))}
              </MapContainer>
            </div>

            {/* CHỈ HIỆN BẢNG QUẢN LÝ KHI ĐÃ CHỌN QUẬN */}
            {selectedDistrict ? (
              <div className="management-table-section" style={{ marginTop: '30px' }}>
                <div className="table-header">
                  <h3>📊 Bảng dữ liệu kinh doanh</h3>
                  <p>Cập nhật số lượng khách hàng, đơn hàng và doanh thu cho từng phường/xã</p>
                </div>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Mã Zone</th>
                      <th>Tên Phường/Xã</th>
                      <th>Khách hàng</th>
                      <th>Đơn hàng</th>
                      <th>Doanh thu (VND)</th>
                      <th>Thao tác</th>
                    </tr>
                  </thead>
                  <tbody>
                    {displayedZones.map(z => (
                      <tr key={z.id}>
                        <td><strong>{z.zone_code}</strong></td>
                        <td>{z.name}</td>
                        <td>{z.num_customers}</td>
                        <td>{z.num_orders}</td>
                        <td>{z.revenue.toLocaleString()}</td>
                        <td>
                          <button className="btn-edit" onClick={() => setEditingZone(z)}>✏️ Sửa</button>
                          <button className="btn-delete" onClick={() => handleDeleteZone(z.id)}>🗑️ Xóa</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="empty-state-notice">
                <p>💡 Vui lòng chọn một <strong>Quận</strong> ở menu bên trái để bắt đầu quản lý chi tiết các Zones.</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Modal Chỉnh sửa thông tin Zone */}
      {editingZone && (
        <div className="edit-overlay">
          <div className="edit-modal">
            <h3>Cập nhật dữ liệu: {editingZone.name}</h3>
            <form onSubmit={handleUpdateZone}>
              <div className="form-group">
                <label>Số lượng khách hàng:</label>
                <input type="number" value={editingZone.num_customers} onChange={e => setEditingZone({...editingZone, num_customers: e.target.value})} required />
              </div>
              <div className="form-group">
                <label>Số lượng đơn hàng:</label>
                <input type="number" value={editingZone.num_orders} onChange={e => setEditingZone({...editingZone, num_orders: e.target.value})} required />
              </div>
              <div className="form-group">
                <label>Doanh thu dự kiến (VND):</label>
                <input type="number" value={editingZone.revenue} onChange={e => setEditingZone({...editingZone, revenue: e.target.value})} required />
              </div>
              <div className="form-actions">
                <button type="submit" className="btn-success">💾 Lưu thông tin</button>
                <button type="button" className="btn-secondary" onClick={() => setEditingZone(null)}>Hủy</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
